//! Criterion benchmark: full TLS 1.3 handshake vs resumed session.
//!
//! Uses an in-memory duplex pipe (tokio `io::duplex`) and a local
//! self-signed certificate generated by `oxitls-rcgen` to measure:
//! - `full_handshake`: fresh client + server configs, no session tickets.
//! - `resumed_handshake`: client and server configs allow session resumption
//!   (default); a first handshake seeds the ticket and the second reuses it.

use criterion::{criterion_group, criterion_main, Criterion};
use oxitls_adapter_rustls_rustcrypto::{
    RustcryptoAcceptor, RustcryptoClientConfigBuilder, RustcryptoConnector,
    RustcryptoServerConfigBuilder, ServerName,
};
use oxitls_rcgen::generate_self_signed_ed25519;
use rustls::RootCertStore;
use rustls_pki_types::{PrivateKeyDer, PrivatePkcs8KeyDer};
use std::sync::Arc;

/// Build a matched client + server config pair from a fresh self-signed cert.
fn make_configs() -> (Arc<rustls::ClientConfig>, Arc<rustls::ServerConfig>) {
    let ck = generate_self_signed_ed25519(&["localhost"]).expect("cert gen");

    // Server config.
    let cert_der = rustls_pki_types::CertificateDer::from(ck.cert_der.clone());
    let key = PrivateKeyDer::Pkcs8(PrivatePkcs8KeyDer::from(ck.pkcs8_der.clone()));
    let server_cfg = RustcryptoServerConfigBuilder::new()
        .with_cert_and_key(vec![cert_der.clone()], key)
        .build()
        .expect("server cfg");

    // Client config trusting only our cert.
    let mut roots = RootCertStore::empty();
    roots.add(cert_der).expect("add cert");
    let client_cfg = RustcryptoClientConfigBuilder::new()
        .with_roots(roots)
        .with_resumption_disabled()
        .build()
        .expect("client cfg");

    (Arc::new(client_cfg), Arc::new(server_cfg))
}

/// Build configs where the client allows session resumption.
fn make_configs_resumable() -> (Arc<rustls::ClientConfig>, Arc<rustls::ServerConfig>) {
    let ck = generate_self_signed_ed25519(&["localhost"]).expect("cert gen");

    let cert_der = rustls_pki_types::CertificateDer::from(ck.cert_der.clone());
    let key = PrivateKeyDer::Pkcs8(PrivatePkcs8KeyDer::from(ck.pkcs8_der.clone()));
    let server_cfg = RustcryptoServerConfigBuilder::new()
        .with_cert_and_key(vec![cert_der.clone()], key)
        .build()
        .expect("server cfg");

    let mut roots = RootCertStore::empty();
    roots.add(cert_der).expect("add cert");
    // Default — session tickets enabled.
    let client_cfg = RustcryptoClientConfigBuilder::new()
        .with_roots(roots)
        .build()
        .expect("client cfg");

    (Arc::new(client_cfg), Arc::new(server_cfg))
}

/// Run one full TLS handshake over a duplex pipe.
///
/// Returns immediately after the handshake completes; no application data
/// is exchanged.
async fn do_handshake(
    client_cfg: Arc<rustls::ClientConfig>,
    server_cfg: Arc<rustls::ServerConfig>,
) {
    let (client_io, server_io) = tokio::io::duplex(65_536);
    let connector = RustcryptoConnector::new(client_cfg);
    let acceptor = RustcryptoAcceptor::new(server_cfg);
    let sn = ServerName::try_from("localhost".to_string()).expect("valid server name");

    let (client_res, server_res) =
        tokio::join!(connector.connect(sn, client_io), acceptor.accept(server_io),);
    client_res.expect("client handshake");
    server_res.expect("server handshake");
}

fn bench_full_handshake(c: &mut Criterion) {
    let rt = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("tokio runtime");

    c.bench_function("handshake/full_tls13_no_resumption", |b| {
        b.iter(|| {
            let (client_cfg, server_cfg) = make_configs();
            rt.block_on(do_handshake(client_cfg, server_cfg));
        });
    });
}

fn bench_resumed_handshake(c: &mut Criterion) {
    let rt = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("tokio runtime");

    c.bench_function("handshake/tls13_with_resumption_allowed", |b| {
        b.iter(|| {
            let (client_cfg, server_cfg) = make_configs_resumable();
            rt.block_on(do_handshake(client_cfg, server_cfg));
        });
    });
}

criterion_group!(benches, bench_full_handshake, bench_resumed_handshake);
criterion_main!(benches);
